import pandas as pd
import numpy as np
from sklearn.preprocessing import LabelEncoder

def task_func(num_samples, countries=['Russia', 'China', 'USA', 'India', 'Brazil'], 
           ages=np.arange(18, 60), genders=['Male', 'Female'], rng_seed=None):
    if isinstance(num_samples, (bool, np.bool_)) or not isinstance(num_samples, (int, np.integer)):
        raise ValueError("num_samples must be an integer.")

    if num_samples < 0:
        raise ValueError("num_samples must be non-negative.")

    if len(countries) == 0:
        raise ValueError("countries must not be empty.")
    if len(ages) == 0:
        raise ValueError("ages must not be empty.")
    if len(genders) == 0:
        raise ValueError("genders must not be empty.")

    rng = np.random.default_rng(rng_seed)

    sampled_countries = rng.choice(countries, size=num_samples)
    sampled_ages = rng.choice(ages, size=num_samples)
    sampled_genders = rng.choice(genders, size=num_samples)

    encoder = LabelEncoder()
    encoder.fit(genders)
    encoded_genders = encoder.transform(sampled_genders)

    return pd.DataFrame({
        "Country": sampled_countries,
        "Age": sampled_ages,
        "Gender": encoded_genders
    })
